mapper.select:
SELECT x.block_idx, x.source_history_block_idx, x.user_idx, u.user_id, u.nickname, u.user_email, x.block_type, x.blocked_ip, x.is_active AS active, x.reason, x.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, x.released_by_user_idx, ru.nickname AS released_by_nickname, x.blocked_at, x.released_at, x.expires_at, x.block_request_id, x.block_target_key, x.snapshot_status, x.last_history_at, x.synced_at, x.updated_by_user_idx, h.block_scope, h.ip_match_type FROM USER_BLOCKLIST x LEFT JOIN USERS u ON u.user_idx = x.user_idx LEFT JOIN USERS bu ON bu.user_idx = x.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = x.released_by_user_idx LEFT JOIN USER_BLOCK_HISTORY h ON h.block_idx = x.source_history_block_idx WHERE 1=1
AND x.is_active = 1 AND x.is_active = 0
AND COALESCE(h.block_scope, 'USER_ACTION') = #{scope}
AND x.block_type = #{blockType}
AND h.ip_block_batch_idx = #{batchId}
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') OR x.blocked_ip LIKE CONCAT('%', #{keyword}, '%') OR x.reason LIKE CONCAT('%', #{keyword}, '%') OR x.block_target_key LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY x.is_active DESC, x.blocked_at DESC, x.block_idx DESC LIMIT #{limit}

SELECT
FROM IP_BLOCKLIST ip LEFT JOIN USERS bu ON bu.user_idx = ip.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = ip.released_by_user_idx LEFT JOIN USERS mu ON mu.user_idx = ip.manual_override_by_user_idx LEFT JOIN USERS lcu ON lcu.user_idx = ip.last_control_by_user_idx LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = ip.ip_block_batch_idx WHERE 1=1
AND ip.is_active = 1 AND ip.is_active = 0
AND ip.source_scope = #{scope}
AND ip.match_type = #{matchType}
AND ip.block_type = #{blockType}
AND ip.rule_action = #{ruleAction}
AND ip.control_mode = #{controlMode}
AND ip.block_category = #{category}
AND ip.ip_block_batch_idx = #{batchId}
AND ip.effective_status = #{effectiveStatus}
AND ( ip.ip_address LIKE CONCAT('%', #{keyword}, '%') OR ip.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR ip.cidr_notation LIKE CONCAT('%', #{keyword}, '%') OR ip.range_start_ip LIKE CONCAT('%', #{keyword}, '%') OR ip.range_end_ip LIKE CONCAT('%', #{keyword}, '%') OR ip.country_code LIKE CONCAT('%', #{keyword}, '%') OR ip.asn LIKE CONCAT('%', #{keyword}, '%') OR ip.reason LIKE CONCAT('%', #{keyword}, '%') OR ip.detail_message LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ip.is_effective_active DESC, ip.priority DESC, CASE WHEN ip.rule_action = 'BLOCK' THEN 0 ELSE 1 END ASC, ip.updated_at DESC, ip.ip_blocklist_idx DESC LIMIT #{limit}

