mapper.select:
SELECT h.block_idx, h.rule_action, h.control_mode, h.operation_source, h.user_idx, u.user_id, u.nickname, h.block_type, h.blocked_ip, h.is_active AS active, h.reason, h.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, h.released_by_user_idx, ru.nickname AS released_by_nickname, h.blocked_at, h.released_at, h.expires_at, h.block_request_id, h.block_target_key, h.user_blocklist_idx, h.ip_blocklist_idx, h.history_kind, h.block_scope, h.ip_match_type, h.cidr_notation, h.range_start_ip, h.range_end_ip, h.ip_block_batch_idx, h.batch_operation_idx, b.batch_code, b.batch_name, h.list_synced_at, h.before_rule_is_active, h.after_rule_is_active, h.before_batch_is_active, h.after_batch_is_active, h.before_effective_active, h.after_effective_active, h.before_effective_status, h.after_effective_status, h.effective_result, h.control_reason FROM USER_BLOCK_HISTORY h LEFT JOIN USERS u ON u.user_idx = h.user_idx LEFT JOIN USERS bu ON bu.user_idx = h.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = h.released_by_user_idx LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = h.ip_block_batch_idx WHERE 1=1
AND h.is_active = 1 AND h.is_active = 0
AND h.block_scope = #{scope}
AND COALESCE(h.ip_match_type, 'SINGLE_IP') = #{matchType}
AND h.block_type = #{blockType}
AND h.rule_action = #{ruleAction}
AND h.control_mode = #{controlMode}
AND h.ip_block_batch_idx = #{batchId}
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR h.blocked_ip LIKE CONCAT('%', #{keyword}, '%') OR h.reason LIKE CONCAT('%', #{keyword}, '%') OR h.control_reason LIKE CONCAT('%', #{keyword}, '%') OR h.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR h.cidr_notation LIKE CONCAT('%', #{keyword}, '%') OR h.range_start_ip LIKE CONCAT('%', #{keyword}, '%') OR h.range_end_ip LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY h.blocked_at DESC, h.block_idx DESC LIMIT #{limit}

