WHERE 1=1
AND h.is_active = 1 AND h.is_active = 0
AND h.block_scope = #{scope}
AND COALESCE(h.ip_match_type, 'SINGLE_IP') = #{matchType}
AND h.block_type = #{blockType}
AND h.rule_action = #{ruleAction}
AND h.control_mode = #{controlMode}
AND h.ip_block_batch_idx = #{batchId}
AND (h.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR h.blocked_ip LIKE CONCAT('%', #{keyword}, '%'))
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
AND (h.reason LIKE CONCAT('%', #{keyword}, '%') OR h.control_reason LIKE CONCAT('%', #{keyword}, '%'))
AND (h.history_kind LIKE CONCAT('%', #{keyword}, '%') OR h.control_mode LIKE CONCAT('%', #{keyword}, '%') OR h.operation_source LIKE CONCAT('%', #{keyword}, '%'))
AND (b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%'))
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR h.blocked_ip LIKE CONCAT('%', #{keyword}, '%') OR h.reason LIKE CONCAT('%', #{keyword}, '%') OR h.control_reason LIKE CONCAT('%', #{keyword}, '%') OR h.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR h.cidr_notation LIKE CONCAT('%', #{keyword}, '%') OR h.range_start_ip LIKE CONCAT('%', #{keyword}, '%') OR h.range_end_ip LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT h.block_idx, h.rule_action, h.control_mode, h.operation_source, h.user_idx, u.user_id, u.nickname, h.block_type, h.blocked_ip, h.is_active AS active, h.reason, h.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, h.released_by_user_idx, ru.nickname AS released_by_nickname, h.blocked_at, h.released_at, h.expires_at, h.block_request_id, h.block_target_key, h.user_blocklist_idx, h.ip_blocklist_idx, h.history_kind, h.block_scope, h.ip_match_type, h.cidr_notation, h.range_start_ip, h.range_end_ip, h.ip_block_batch_idx, h.batch_operation_idx, b.batch_code, b.batch_name, h.list_synced_at, h.before_rule_is_active, h.after_rule_is_active, h.before_batch_is_active, h.after_batch_is_active, h.before_effective_active, h.after_effective_active, h.before_effective_status, h.after_effective_status, h.effective_result, h.control_reason FROM USER_BLOCK_HISTORY h LEFT JOIN USERS u ON u.user_idx = h.user_idx LEFT JOIN USERS bu ON bu.user_idx = h.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = h.released_by_user_idx LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = h.ip_block_batch_idx
ORDER BY h.blocked_at ASCDESC, h.block_idx DESC ORDER BY h.block_target_key ASCDESC, h.block_idx DESC ORDER BY h.rule_action ASCDESC, h.block_idx DESC ORDER BY h.history_kind ASCDESC, h.block_idx DESC ORDER BY h.effective_result ASCDESC, h.block_idx DESC ORDER BY COALESCE(h.control_reason, h.reason) ASCDESC, h.block_idx DESC ORDER BY h.blocked_at DESC, h.block_idx DESC
LIMIT #{size} OFFSET #{offset}

SELECT b.ip_block_batch_idx, b.batch_code, b.batch_name, b.source_type, b.source_name, b.batch_rule_action, b.default_rule_priority, b.is_active AS active, b.description, b.default_disable_strategy, b.default_enable_strategy, b.created_by_user_idx, cu.nickname AS created_by_nickname, b.updated_by_user_idx, uu.nickname AS updated_by_nickname, b.created_at, b.updated_at, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx) AS total_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.is_active = 1) AS active_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.is_effective_active = 1) AS effective_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.effective_status = 'EXPIRED') AS expired_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.control_mode = 'BATCH') AS batch_managed_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.control_mode = 'MANUAL_OVERRIDE') AS manual_override_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.rule_action = 'ALLOW') AS allow_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.rule_action = 'BLOCK') AS block_rule_count FROM IP_BLOCK_BATCH b LEFT JOIN USERS cu ON cu.user_idx = b.created_by_user_idx LEFT JOIN USERS uu ON uu.user_idx = b.updated_by_user_idx WHERE 1=1
AND ( b.batch_code LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.source_name LIKE CONCAT('%', #{keyword}, '%') OR b.description LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY b.is_active DESC, b.updated_at DESC, b.ip_block_batch_idx DESC LIMIT #{limit}

SELECT o.ip_block_batch_operation_idx, o.ip_block_batch_idx, b.batch_code, b.batch_name, o.operation_type, o.operation_option, o.requested_rule_count, o.affected_rule_count, o.description, o.requested_by_user_idx, u.nickname AS requested_by_nickname, o.requested_at FROM IP_BLOCK_BATCH_OPERATION o LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = o.ip_block_batch_idx LEFT JOIN USERS u ON u.user_idx = o.requested_by_user_idx WHERE 1=1
AND o.ip_block_batch_idx = #{batchId}
AND ( o.operation_type LIKE CONCAT('%', #{keyword}, '%') OR o.operation_option LIKE CONCAT('%', #{keyword}, '%') OR o.description LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY o.requested_at DESC, o.ip_block_batch_operation_idx DESC LIMIT #{limit}

mapper.insert:
