    ip_block_batch_idx, operation_type, operation_option,
    requested_rule_count, affected_rule_count, description,
    requested_by_user_idx, requested_at
) VALUES (
    #{ipBlockBatchIdx}, #{operationType}, #{operationOption},
    #{requestedRuleCount}, #{affectedRuleCount}, #{description},
    #{requestedByUserIdx}, #{requestedAt}
)

mapper.update:
UPDATE IP_BLOCK_BATCH_OPERATION
SET affected_rule_count = #{affectedRuleCount}
WHERE ip_block_batch_operation_idx = #{ipBlockBatchOperationIdx}

